async function resolveTeamOption(
  competitorId: string,
  signal: AbortSignal,
): Promise<NameComboboxOption | null> {
  try {
    const response = await publicReadApi.getCompetitor(competitorId, signal);
    return { label: response.data.name, value: response.data.competitorId };
  } catch {
    return null;
  }
}

async function loadTeamNameOptions(
  filters: URLSearchParams,
  query: string,
  signal: AbortSignal,
): Promise<NameComboboxOption[]> {
  const options = await loadTeamOptions(filters, query, signal);
  return options.map((option) => ({ ...option, value: option.label }));
}

async function loadPlayerNameOptions(
  filters: URLSearchParams,
  query: string,
  signal: AbortSignal,
): Promise<NameComboboxOption[]> {
  const response = await publicReadApi.listParticipants(optionSearch(filters, query), signal);
  return response.data.map((player) => ({
    label: player.displayName,
    value: player.displayName,
  }));
}

